          const codeId = json.data.path;
          const cloudCommand = `云6oooole/xxxxxx/${codeId}`;
          const fullShareCommand = `${cloudCommand}\n小程序：${title}`;
          const webUrl = `https://pasteme.tyrantg.com/[REDACTED_REMOTE_URL]          return {
            success: true,
            provider: 'pasteme',
            cloudCommand,
            fullShareCommand,
            codeId,
            webUrl,
            standardCommand,
            title
          };
        }
      }
    } catch (err) {
      console.warn('[ExportCommand] PasteMe 上传超时或失败，尝试备用 cmd.im:', err.message);
    }
  }

  // 2. 备用 cmd.im (云5oooole)
  try {
    const res = await fetch('https://cmd.im/[REDACTED_REMOTE_URL]', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
      },
      body: `txt=${encodeURIComponent(standardCommand)}`,
      redirect: 'manual',
      signal: AbortSignal.timeout(10000)
    });
