    if (location) {
      const codeId = location.replace(/^\/+/, '');
      const cloudCommand = `云5oooole/xxxxxx/${codeId}`;
      const fullShareCommand = `${cloudCommand}\n小程序：${title}`;
      const webUrl = `https://cmd.im/[REDACTED_REMOTE_URL]      return {
